from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equally many even and odd digits
    that are divisible by k.

    Args:
        low: Inclusive lower bound, 0 < low <= high <= 10**9.
        high: Inclusive upper bound.
        k: Divisor, 0 < k <= 20.

    >>> count_beautiful_integers(10, 20, 3)
    2
    >>> count_beautiful_integers(1, 10, 1)
    1
    >>> count_beautiful_integers(5, 5, 2)
    0
    """

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        size = len(digits)

        @lru_cache(maxsize=None)
        def count(pos: int, balance: int, remainder: int,
                  started: bool, tight: bool) -> int:
            if pos == size:
                return int(started and balance == 0 and remainder == 0)
            remaining = size - pos
            if abs(balance) > remaining:
                return 0
            if started and (remaining - balance) % 2:
                return 0

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == digits[pos]
                if not started and digit == 0:
                    total += count(pos + 1, 0, 0, False, next_tight)
                else:
                    total += count(
                        pos + 1,
                        balance + (1 if digit % 2 == 0 else -1),
                        (remainder * 10 + digit) % k,
                        True,
                        next_tight,
                    )
            return total

        return count(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

from functools import lru_cache


@lru_cache(maxsize=None)
def _count_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count unrestricted suffixes; sum zero denotes an unstarted number."""
    if remaining == 0:
        return int(digit_sum > 0 and product % digit_sum == 0)
    if product == 0:
        # A real zero digit makes every completion beautiful.
        return 10 ** remaining
    total = 0
    for digit in range(10):
        next_product = product * digit if digit_sum or digit else 1
        total += _count_suffix(remaining - 1, digit_sum + digit, next_product)
    return total


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    total = 0
    digit_sum = 0
    product = 1
    for position, limit in enumerate(digits):
        remaining = len(digits) - position - 1
        for digit in range(limit):
            next_product = product * digit if digit_sum or digit else 1
            total += _count_suffix(remaining, digit_sum + digit, next_product)
        product = product * limit if digit_sum or limit else 1
        digit_sum += limit
    return total + int(digit_sum > 0 and product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when its digit product is divisible by its digit
    sum. Bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

