from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles exactly covers the grid.

    Each available tile may be used at most once. Tiles must align with grid
    cells, must not overlap, and cannot extend outside the h by w grid.
    """
    shapes = sorted(
        (tuple(sorted((a, b))) for a, b in tiles[:n]
         if (a <= h and b <= w) or (b <= h and a <= w)),
        key=lambda shape: shape[0] * shape[1],
        reverse=True,
    )
    count = len(shapes)
    cells = h * w
    full = (1 << cells) - 1

    # attainable[mask] has bit s set exactly when some subset of mask has area s.
    attainable = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        a, b = shapes[bit.bit_length() - 1]
        previous = attainable[mask ^ bit]
        attainable[mask] = previous | (previous << (a * b))

    placements = [[] for _ in range(cells)]
    for pos in range(cells):
        row, col = divmod(pos, w)
        for i, (a, b) in enumerate(shapes):
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    rectangle = 0
                    row_bits = (1 << width) - 1
                    for offset in range(height):
                        rectangle |= row_bits << (pos + offset * w)
                    placements[pos].append((i, rectangle))

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = cells - occupied.bit_count()
        if not (attainable[remaining] >> needed) & 1:
            return False

        # A tile covering the first empty cell must start at that cell:
        # every earlier cell is already occupied.
        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1
        tried = set()
        for i, rectangle in placements[pos]:
            bit = 1 << i
            if not remaining & bit or rectangle & occupied:
                continue
            key = (shapes[i], rectangle)
            if key in tried:
                continue
            tried.add(key)
            if search(occupied | rectangle, remaining ^ bit):
                return True
        return False

    return search(0, (1 << count) - 1)

from collections import deque
from functools import lru_cache
from typing import List


@lru_cache(maxsize=1)
def _knight_graph():
    """Legal knight destinations for each square of the 50 by 50 board."""
    steps = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))
    graph = [[] for _ in range(2500)]
    for x in range(50):
        for y in range(50):
            for dx, dy in steps:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50:
                    graph[x * 50 + y].append(nx * 50 + ny)
    return graph


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    Return the total moves under optimal alternating pawn captures.

    The knight stays on a 50x50 board and each capture follows a shortest
    knight path. Alice maximizes total moves and Bob minimizes them, with
    Alice moving first. Other pawns do not block or force captures along
    the path. There are at most 15 pawns.
    """
    n = len(positions)
    squares = [x * 50 + y for x, y in positions] + [kx * 50 + ky]
    graph = _knight_graph()
    distances = []
    for start in squares:
        distance = [-1] * 2500
        distance[start] = 0
        queue = deque([start])
        while queue:
            square = queue.popleft()
            next_distance = distance[square] + 1
            for neighbor in graph[square]:
                if distance[neighbor] == -1:
                    distance[neighbor] = next_distance
                    queue.append(neighbor)
        distances.append([distance[target] for target in squares[:n]])

    @lru_cache(maxsize=None)
    def play(current: int, remaining: int) -> int:
        if not remaining:
            return 0
        alice_turn = (n - remaining.bit_count()) % 2 == 0
        best = -1 if alice_turn else 10 ** 9
        candidates = remaining
        while candidates:
            bit = candidates & -candidates
            pawn = bit.bit_length() - 1
            value = distances[current][pawn] + play(pawn, remaining ^ bit)
            if alice_turn:
                if value > best:
                    best = value
            elif value < best:
                best = value
            candidates ^= bit
        return best

    return play(n, (1 << n) - 1)

