from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    overflow = limit + 1
    dp = {}
    for value in nums:
        nxt = dp.copy()
        product = min(value, overflow)
        even, odd = nxt.get(product, (0, 0))
        nxt[product] = (even, odd | (1 << (bound + value)))
        for product, (even, odd) in dp.items():
            target = 0 if value == 0 else min(overflow, product * value)
            old_even, old_odd = nxt.get(target, (0, 0))
            nxt[target] = (old_even | (odd >> value),
                           old_odd | (even << value))
        dp = nxt
    bit = 1 << (bound + k)
    return max((product for product, (even, odd) in dp.items()
                if product <= limit and (even | odd) & bit), default=-1)

