from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Return maximum permitted product of a nonempty subsequence with alternating sum k."""
    offset = 12 * len(nums)
    if abs(k) > offset:
        return -1
    overflow = limit + 1
    even = {}
    odd = {}
    for value in nums:
        next_even = even.copy()
        next_odd = odd.copy()
        for product, sums in even.items():
            nxt = min(overflow, product * value)
            next_odd[nxt] = next_odd.get(nxt, 0) | (sums << value)
        for product, sums in odd.items():
