def count_strings_by_lcs_length(n: int, m: int, s: str) -> list[int]:
    mod = 998244353
    masks = {}
    for i, char in enumerate(s):
        masks[char] = masks.get(char, 0) | (1 << i)
    letters = list(masks.values())
    size = 1 << n
    transitions = []
    for state in range(size):
        row = []
        for char_mask in letters:
            x = state | char_mask
            row.append(x & ~(x - ((state << 1) | 1)))
        transitions.append(row)
    dp = [0] * size
    dp[0] = 1
    absent = 26 - len(letters)
    for _ in range(m):
        next_dp = [count * absent % mod for count in dp]
        for state, count in enumerate(dp):
            if count:
                for target in transitions[state]:
                    next_dp[target] = (next_dp[target] + count) % mod
        dp = next_dp
    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + count) % mod
    return answer
