def max_product_subsequence(nums: list[int], k: int, limit: int) -> int:
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    cap = limit + 1
    dp = {}
    for x in nums:
        next_dp = dp.copy()
        for product, (even, odd) in dp.items():
            target = min(cap, product * x)
            old_even, old_odd = next_dp.get(target, (0, 0))
            next_dp[target] = (old_even | (odd >> x), old_odd | (even << x))
        target = min(cap, x)
        old_even, old_odd = next_dp.get(target, (0, 0))
        next_dp[target] = (old_even, old_odd | (1 << (offset + x)))
        dp = next_dp
    bit = 1 << (offset + k)
    return max((product for product, (even, odd) in dp.items()
