def count_strings_by_lcs_length(n, m, s):
    mod = 998244353
    letters = set(s)
    size = 1 << n
    transitions = []
    for char in letters:
        table = []
        for mask in range(size):
            previous = current = newmask = 0
            for j in range(n):
                old = previous + ((mask >> j) & 1)
                new = max(old, current, previous + (s[j] == char))
                if new > current:
                    newmask |= 1 << j
                previous, current = old, new
            table.append(newmask)
        transitions.append(table)
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [v * (26 - len(letters)) % mod for v in dp]
        for mask, ways in enumerate(dp):
            if ways:
                for table in transitions:
                    target = table[mask]
                    next_dp[target] = (next_dp[target] + ways) % mod
        dp = next_dp
    result = [0] * (n + 1)
    for mask, ways in enumerate(dp):
        k = mask.bit_count()
        result[k] = (result[k] + ways) % mod
    return result
