def max_product_subsequence(nums, k, limit):
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    dp = {}
    cap = limit + 1
    for x in nums:
        nxt = dp.copy()
        for product, (even, odd) in dp.items():
            product2 = min(product * x, cap)
            e, o = nxt.get(product2, (0, 0))
            nxt[product2] = (e | (odd >> x), o | (even << x))
        singleton = min(x, cap)
        e, o = nxt.get(singleton, (0, 0))
        nxt[singleton] = (e, o | (1 << (bound + x)))
        dp = nxt
    target = 1 << (bound + k)
    return max((p for p, (e, o) in dp.items()
                if p <= limit and (e | o) & target), default=-1)

