    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        nxt = [0] * size
        for state, ways in enumerate(dp):
            if ways:
                for dest, weight in transitions[state]:
                    nxt[dest] = (nxt[dest] + ways * weight) % mod
        dp = nxt
    answer = [0] * (n + 1)
    for state, ways in enumerate(dp):
        k = state.bit_count()
        answer[k] = (answer[k] + ways) % mod
    return answer
