    for mask in range(1, 1 << count):
        bit = mask & -mask
        a, b = shapes[bit.bit_length() - 1]
        previous = attainable[mask ^ bit]
        attainable[mask] = previous | (previous << (a * b))

    placements = [[] for _ in range(cells)]
    for pos in range(cells):
        row, col = divmod(pos, w)
        for i, (a, b) in enumerate(shapes):
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    rectangle = 0
                    row_bits = (1 << width) - 1
                    for offset in range(height):
                        rectangle |= row_bits << (pos + offset * w)
                    placements[pos].append((i, rectangle))

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = cells - occupied.bit_count()
        if not (attainable[remaining] >> needed) & 1:
            return False

        # A tile covering the first empty cell must start at that cell:
        # every earlier cell is already occupied.
        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1
        tried = set()
        for i, rectangle in placements[pos]:
            bit = 1 << i
            if not remaining & bit or rectangle & occupied:
                continue
            key = (shapes[i], rectangle)
            if key in tried:
                continue
            tried.add(key)
            if search(occupied | rectangle, remaining ^ bit):
                return True
        return False

    return search(0, (1 << count) - 1)

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles exactly covers the grid.

    Each available tile may be used at most once. Tiles must align with grid
    cells, must not overlap, and cannot extend outside the h by w grid.
    """
    shapes = sorted(
        (tuple(sorted((a, b))) for a, b in tiles[:n]
         if (a <= h and b <= w) or (b <= h and a <= w)),
        key=lambda shape: shape[0] * shape[1],
        reverse=True,
    )
    count = len(shapes)
    cells = h * w
    full = (1 << cells) - 1

    # attainable[mask] has bit s set exactly when some subset of mask has area s.
    attainable = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        a, b = shapes[bit.bit_length() - 1]
        previous = attainable[mask ^ bit]
        attainable[mask] = previous | (previous << (a * b))

    placements = [[] for _ in range(cells)]
    for pos in range(cells):
        row, col = divmod(pos, w)
        for i, (a, b) in enumerate(shapes):
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    rectangle = 0
                    row_bits = (1 << width) - 1
                    for offset in range(height):
                        rectangle |= row_bits << (pos + offset * w)
                    placements[pos].append((i, rectangle))

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = cells - occupied.bit_count()
        if not (attainable[remaining] >> needed) & 1:
            return False

        # A tile covering the first empty cell must start at that cell:
        # every earlier cell is already occupied.
        empty = full ^ occupied
        pos = (empty & -empty).bit_length() - 1
        tried = set()
        for i, rectangle in placements[pos]:
            bit = 1 << i
            if not remaining & bit or rectangle & occupied:
                continue
            key = (shapes[i], rectangle)
            if key in tried:
                continue
            tried.add(key)
            if search(occupied | rectangle, remaining ^ bit):
                return True
        return False

    return search(0, (1 << count) - 1)

from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    upper = denominations[0] * k
    # Combine inclusion-exclusion terms with the same least common multiple.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            if common <= upper:
                changes[common] = changes.get(common, 0) - coefficient
        for multiple, coefficient in changes.items():
            combined = coefficients.get(multiple, 0) + coefficient
            if combined:
                coefficients[multiple] = combined
            else:
                coefficients.pop(multiple, None)

    lower = 1
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in coefficients.items())
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions, and replacements can turn s
    into t using at most k operations.

    Supports strings of length up to 500000 and budgets up to 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    # For each diagonal d = x - y, keep the largest source position x
    # reachable with the current edit budget, after matching equal characters.
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        return True
    previous = {0: x}

    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            best = -1

            # Replace the next character.
            old = previous.get(diagonal)
            if old is not None and old < n and old - diagonal < m:
                best = old + 1

            # Delete the next source character.
            old = previous.get(diagonal - 1)
            if old is not None and old < n:
                best = max(best, old + 1)

            # Insert the next target character.
            old = previous.get(diagonal + 1)
            if old is not None and old - (diagonal + 1) < m:
                best = max(best, old)

            if best < 0:
                continue
            x = best
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            current[diagonal] = x
        previous = current
    return False

